#include <stdio.h>
int n;
void pa(int a[], int n) { for(int i=0; i<n; i++) printf("%d%c", a[i], i==n-1?'\n':' '); }
void swap(int* a, int* b) { int t = *a; *a = *b; *b = t; }
void heapify(int arr[], int sz, int i) {
    int largest = i; int l = 2 * i + 1; int r = 2 * i + 2;
    if (l < sz && arr[l] > arr[largest]) largest = l;
    if (r < sz && arr[r] > arr[largest]) largest = r;
    if (largest != i) { swap(&arr[i], &arr[largest]); heapify(arr, sz, largest); }
}
void heapSort(int arr[], int sz) {
    for (int i = sz / 2 - 1; i >= 0; i--) heapify(arr, sz, i);
    pa(arr, n); 
    for (int i = sz - 1; i > 0; i--) {
        swap(&arr[0], &arr[i]);
        heapify(arr, i, 0);
        pa(arr, n); 
    }
}
int main() {
    if(scanf("%d",&n)!=1) return 0;
    if(n==0) { printf("\n"); return 0; }
    int a[1005]; for(int i=0; i<n; i++) scanf("%d", &a[i]);
    if(n==1) { pa(a,n); return 0; }
    heapSort(a, n);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int n;
void pa(int a[], int sz) { for(int i=0; i<sz; i++) printf("%d%c", a[i], i==sz-1?'\n':' '); }
int getMax(int arr[], int sz) { int mx = arr[0]; for (int i = 1; i < sz; i++) if (arr[i] > mx) mx = arr[i]; return mx; }
void countSort(int arr[], int sz, int exp) {
    int* output = (int*)malloc(sz * sizeof(int)); int i, count[10] = { 0 };
    for (i = 0; i < sz; i++) count[(arr[i] / exp) % 10]++;
    for (i = 1; i < 10; i++) count[i] += count[i - 1];
    for (i = sz - 1; i >= 0; i--) { output[count[(arr[i] / exp) % 10] - 1] = arr[i]; count[(arr[i] / exp) % 10]--; }
    for (i = 0; i < sz; i++) arr[i] = output[i];
    pa(arr, sz);
    free(output);
}
void radixSort(int arr[], int sz) {
    if(sz <= 0) return;
    int m = getMax(arr, sz);
    int exp = 1;
    do {
        countSort(arr, sz, exp);
        exp *= 10;
    } while(m / exp > 0);
}
int main() {
    if(scanf("%d",&n)!=1) return 0;
    if(n==0) { printf("\n"); return 0; }
    int a[1005]; for(int i=0; i<n; i++) scanf("%d", &a[i]);
    if(n==1) { pa(a,n); return 0; }
    radixSort(a, n);
    return 0;
}
